  balanceInstruction = 'IMPORTANT: Portfolio is ETF-heavy. You MUST include at least 2 growth stocks in your trades today. Lean toward PLTR_US_EQ, AMD_US_EQ, SOFI_US_EQ, IONQ_US_EQ, RKLB_US_EQ, HOOD_US_EQ, COIN_US_EQ, AFRM_US_EQ.';
