const raw = $input.item.json.message?.content || 
            $input.item.json.content || '';
const cash = $('Build Ollama Prompt').item.json.cash || 0;

let parsed;
try {
  const start = raw.indexOf('{');
  const end = raw.lastIndexOf('}');
  if (start === -1 || end === -1) throw new Error('No JSON found');
  const jsonStr = raw.substring(start, end + 1)
    .replace(/\/\/[^\n]*/g, '')
    .replace(/\/\*[\s\S]*?\*\//g, '')
    .replace(/,\s*([}\]])/g, '$1');
  parsed = JSON.parse(jsonStr);
} catch(e) {
  throw new Error('Parse failed: ' + raw.substring(0, 300));
}

const trades = (parsed.trades || []).filter(t => {
  const ticker = t.ticker || t.symbol || '';
  const amount = parseFloat(t.amount || t.totalCost || 0);
  if (!ticker || amount <= 0 || amount > cash) return false;
  return ticker.endsWith('_US_EQ') || ticker.endsWith('l_EQ');
}).map(t => ({
  ticker: t.ticker || t.symbol || '',
  amount: parseFloat(t.amount || t.totalCost || 0),
  reason: t.reason || 'AI trade decision',
  isDip: t.isDip || false
}));

return [{json: {
  trades,
  summary: parsed.summary || '',
  cash,
  tradeCount: trades.length,
  hasDipTrades: trades.some(t => t.isDip)
}}];

