const ticker = $json.ticker || ""; 
const amount = $json.amount || 0;
const reason = $json.reason || "No reason provided";
const isDip = $json.isDip || false;

if (!ticker) {
  return [{ json: { error: "Ticker was missing from input", ticker, amount, reason } }];
}

let yahooSymbol;

// Case 1: US Stocks (e.g. AAPL_US_EQ -> AAPL)
if (ticker.includes('_US_EQ')) {
  yahooSymbol = ticker.replace('_US_EQ', '');
} 
// Case 2: UK Stocks/ETFs (e.g. VUAGl_EQ -> VUAG.L)
else {
  // Strip off the _EQ
  let base = ticker.replace('_EQ', '');

  // Trading212 often adds a lowercase 'l' (for London) or 'x' to the end of ETFs.
  // We need to strip that lowercase letter off to get the real base ticker.
  if (base.match(/[a-z]$/)) {
    base = base.slice(0, -1);
  }

  // Append .L for London Stock Exchange
  yahooSymbol = base + '.L';
}

return [{
  json: {
    ticker,
    amount,
    reason,
    isDip,
    yahooSymbol
  }
}];

const data = $input.item.json;
const ticker = $('Map Ticker to Yahoo').item.json.ticker;
const amount = $('Map Ticker to Yahoo').item.json.amount;
const reason = $('Map Ticker to Yahoo').item.json.reason;
const isDip = $('Map Ticker to Yahoo').item.json.isDip;

const result = data.chart?.result?.[0];
const price = result?.meta?.regularMarketPrice || result?.meta?.previousClose;

if (!price || price <= 0) {
  throw new Error('Could not get price for ' + ticker + ' (Yahoo: ' + $('Map Ticker to Yahoo').item.json.yahooSymbol + ')');
}

const quantity = Math.floor((amount / price) * 100) / 100;

const finalQty = Math.max(quantity, 0.01);
return [{json: {ticker, amount, reason, isDip, price, quantity: finalQty}}];

