const combined = $('Combine All Research').item.json;
const bubble = $input.item.json;
const bubbleContext = bubble.answer || (bubble.results||[]).slice(0,2).map(r=>r.content).join(' ') || '';

let bubbleScore = 0;
const text = bubbleContext.toLowerCase();

const euphoriaWords = ['all-time high','record high','irrational exuberance','melt up','parabolic','euphoria','mania','bubble'];
euphoriaWords.forEach(w => { if(text.includes(w)) bubbleScore++; });

const fearWords = ['correction','bear market','recession','crash','selloff'];
fearWords.forEach(w => { if(text.includes(w)) bubbleScore--; });

if(text.includes('overvalued') || text.includes('stretched valuation')) bubbleScore += 2;
if(text.includes('vix') && (text.includes('below 15') || text.includes('complacency'))) bubbleScore += 2;

bubbleScore = Math.max(0, Math.min(15, bubbleScore));

let riskPhase, positionMultiplier;
if(bubbleScore <= 4) { riskPhase = 'Normal 🟢'; positionMultiplier = 1.0; }
else if(bubbleScore <= 7) { riskPhase = 'Caution 🟡'; positionMultiplier = 0.75; }
else if(bubbleScore <= 9) { riskPhase = 'Elevated 🟠'; positionMultiplier = 0.5; }
else if(bubbleScore <= 12) { riskPhase = 'Euphoria 🔴'; positionMultiplier = 0.25; }
else { riskPhase = 'Critical ⛔'; positionMultiplier = 0; }

return [{json: {
  ...combined,
  bubbleScore,
  riskPhase,
  positionMultiplier,
  bubbleContext: bubbleContext.substring(0, 300)
}}];

const cashData = $('GET Cash Balance').item.json;
const portfolioData = $('GET Portfolio').all ? $('GET Portfolio').all().map(i=>i.json) : [];

let tradeLog = '';
try { tradeLog = $('Read ISA Trade Log').item.json.stdout || ''; } catch(e) {}

const lines = tradeLog.split('\n').filter(l => l.includes(','));
const trades = lines.map(l => {
  const p = l.split(',');
  return {date: p[0], ticker: p[1], action: p[2], pnl: parseFloat(p[4])||0};
}).filter(t => t.action === 'BUY');

const today = new Date().toISOString().split('T')[0];
const todayTrades = trades.filter(t => t.date && t.date.startsWith(today));

let circuitBreakerTriggered = false;
let pauseReason = '';

// Daily trade limit — max 4 buys per day for ISA
if(todayTrades.length >= 4) {
  circuitBreakerTriggered = true;
  pauseReason = 'DAILY LIMIT: ' + todayTrades.length + ' trades placed today';
}

// Cash too low
const cash = cashData.free || 0;
if(cash < 5) {
  circuitBreakerTriggered = true;
  pauseReason = 'INSUFFICIENT CASH: £' + cash.toFixed(2) + ' available';
}

return [{json: {
  cash,
  portfolio: portfolioData,
  circuitBreakerTriggered,
  pauseReason,
  todayTradeCount: todayTrades.length
}}];

